import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

/**
 * Private file storage on local disk (server-only). Files are addressed by a
 * storage key such as "requests/<uuid>.pdf"; keys are generated by the server,
 * never taken from user input. DRAWING_STORAGE_DIR overrides the root
 * (default web/.data/drawings).
 */
export function storageRoot() {
  return (
    process.env.DRAWING_STORAGE_DIR ||
    path.join(process.cwd(), ".data", "drawings")
  );
}

function resolveKey(root: string, key: string) {
  const base = path.resolve(root);
  const full = path.resolve(base, key);
  if (!full.startsWith(base + path.sep))
    throw new Error(`Invalid storage key: ${key}`);
  return full;
}

export class FileStorage {
  constructor(private readonly root = storageRoot()) {}

  async write(key: string, bytes: Uint8Array) {
    const target = resolveKey(this.root, key);
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, bytes);
  }

  async read(key: string) {
    return new Uint8Array(await readFile(resolveKey(this.root, key)));
  }

  async remove(key: string) {
    await rm(resolveKey(this.root, key), { force: true });
  }
}

/** Response headers for a private attachment download. */
export function attachmentHeaders(fileName: string) {
  const safeName = fileName.replace(/[^\w.\- ()]/g, "_");
  return {
    "Content-Type": "application/octet-stream",
    "Content-Disposition": `attachment; filename="${safeName}"`,
    "Cache-Control": "private, no-store",
    "X-Content-Type-Options": "nosniff",
  };
}

/**
 * File types a browser can show safely by itself. Uploads of these types are
 * signature-checked before they are stored, so the declared type is genuine.
 * SVG and HTML are never served inline.
 */
const INLINE_TYPES: Record<string, string> = {
  pdf: "application/pdf",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
};

export function fileExtensionOf(fileName: string) {
  return fileName.split(".").pop()?.toLowerCase() ?? "";
}

export function isPreviewable(fileName: string) {
  return fileExtensionOf(fileName) in INLINE_TYPES;
}

/**
 * Headers for viewing a file in the browser (`?inline=1`). Falls back to a
 * download for types the browser cannot display. Framing is limited to this
 * site so previews can be embedded in INDUSTRIHUB pages only.
 */
export function fileResponseHeaders(fileName: string, inline: boolean) {
  const type = INLINE_TYPES[fileExtensionOf(fileName)];
  if (!inline || !type) return attachmentHeaders(fileName);
  const safeName = fileName.replace(/[^\w.\- ()]/g, "_");
  return {
    "Content-Type": type,
    "Content-Disposition": `inline; filename="${safeName}"`,
    "Cache-Control": "private, no-store",
    "X-Content-Type-Options": "nosniff",
    "Content-Security-Policy": "frame-ancestors 'self'",
  };
}

export function wantsInline(request: Request) {
  return new URL(request.url).searchParams.get("inline") === "1";
}
